const base = $('Code in JavaScript').item.json;
const response = $json;
const raw = response.choices?.[0]?.message?.content ?? response.content ?? response.text ?? '';
function parse(value) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string') return {};
  const cleaned = value.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  try { return JSON.parse(cleaned); } catch (_) {}
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (!m) return {};
  try { return JSON.parse(m[0]); } catch (_) { return {}; }
}
const a = parse(raw);
return { json: {
  ...base,
  is_robotics: a.is_robotics ?? null,
  robotics_relevance: a.robotics_relevance ?? null,
  category: a.category ?? null,
  summary_zh: a.summary_zh ?? null,
  summary_en: a.summary_en ?? null,
  key_facts: a.key_facts ?? [],
  why_it_may_work: a.why_it_may_work ?? null,
  hook: a.hook ?? null,
  target_audience: a.target_audience ?? [],
  analyzed_content_type: a.content_type ?? base.content_type ?? null,
  analyzed_language: a.language ?? base.language ?? null,
  recommended_route: a.recommended_route ?? 'discard',
  priority: a.priority ?? 'C',
  keep: a.keep ?? false,
  analysis_confidence: a.confidence ?? null,
  risk_flags: a.risk_flags ?? [],
  uncertainty: a.uncertainty ?? [],
  analysis_status: Object.keys(a).length ? 'analyzed' : 'parse_failed',
  analyzed_at: new Date().toISOString()
} }

const item = $json;
const keep = item.is_robotics === true && item.keep === true && Number(item.robotics_relevance || 0) >= 60 && ['S', 'A'].includes(item.priority);
let route = 'discard';
if (keep) {
  if (item.analyzed_content_type === 'video' && item.analyzed_language === 'zh') route = 'video_remake';
  else if (item.analyzed_content_type === 'video' && item.analyzed_language === 'en') route = 'video_adapt';
  else if (item.analyzed_content_type === 'image') route = 'image_remake';
  else if (item.analyzed_content_type === 'text') route = 'text_rewrite';
}
return { json: { ...item, keep, final_route: route, next_module: route === 'discard' ? 'archive_or_ignore' : route.startsWith('video') ? 'Video Production' : route.startsWith('image') ? 'Image Production' : 'Text Production', route_decision_at: new Date().toISOString() } };
